// Real navigation history: re-render previous routes so item state never goes stale.
let menuTrail=[],menuRoute=null,menuRestoring=false,menuRouteDepth=0,contextHelpKind='';
function menuRouteSnapshot(kind){const target=typeof loadoutRoute!=='undefined'&&loadoutRoute.kind===kind&&loadoutRoute.target?{...loadoutRoute.target}:null;return {key:'panel:'+kind+':'+JSON.stringify(target),render:()=>{loadoutRoute={kind,target:target?{...target}:null};panel(kind);}};}
function menuRemember(route){route.surface=menuSurface;if(menuRestoring){menuRoute=route;return;}if(menuRoute&&menuRoute.key!==route.key){menuTrail.push(menuRoute);if(menuTrail.length>30)menuTrail.shift();}menuRoute=route;}
function menuPrevious(){if(!paused)return false;const nested=menuRoute&&menuRoute.surface!==menuSurface;if(!nested&&!menuTrail.length)return false;const route=nested?menuRoute:menuTrail.pop();menuRestoring=true;padSettingsOpen=false;padBinding=null;saveMenuOpen=false;savePending=null;try{route.render();menuRoute=route;}finally{menuRestoring=false;}return true;}
const menuJourneyPanelBase=panel;panel=(kind,...args)=>{const outer=menuRouteDepth===0;menuRouteDepth++;let result;try{result=menuJourneyPanelBase(kind,...args);}finally{menuRouteDepth--;}if(outer&&started&&!dead&&menuSurface===kind){menuRemember(menuRouteSnapshot(kind));installContextHelp();}return result;};
function menuWrapRoute(fn,key){return function(...args){const outer=menuRouteDepth===0;menuRouteDepth++;let result;try{result=fn(...args);}finally{menuRouteDepth--;}if(outer&&paused){menuRemember({key:key+':'+JSON.stringify(args),render:()=>menuWrapRoute(fn,key)(...args)});installContextHelp();}return result;};}
showVillage=menuWrapRoute(showVillage,'village');showForge=menuWrapRoute(showForge,'forge');showJobHall=menuWrapRoute(showJobHall,'jobs');showControllerSettings=menuWrapRoute(showControllerSettings,'settings');showSaveManager=menuWrapRoute(showSaveManager,'save');
const menuJourneyCloseBase=closePanel;closePanel=(...args)=>{menuTrail=[];menuRoute=null;return menuJourneyCloseBase(...args);};
const menuJourneyPadBase=padMenu;padMenu=(g,l,r,dt)=>{if(started&&paused&&!dead&&!tutorialGuideOpen&&!practiceLesson()&&!assetRequest&&padEdge(g,'back')){if(menuSurface==='market'&&document.activeElement?.closest('#marketDetail')){if($('marketExchangeConfirm'))marketSelect(marketSelection,true);else menuFocusElement($('card').querySelector('[data-market-index="'+marketSelection+'"]'));return;}if(menuPrevious())return;if(loadoutBack())return;closePanel();return;}return menuJourneyPadBase(g,l,r,dt);};
addEventListener('keydown',e=>{if(e.key==='Escape'&&started&&paused&&!dead&&!tutorialGuideOpen&&!assetRequest&&!/^(INPUT|TEXTAREA|SELECT)$/.test(e.target?.tagName||'')&&menuPrevious()){e.preventDefault();e.stopImmediatePropagation();}},true);
const CONTEXT_MENU_HELP={inventory:['装備とソケット','部位を選ぶと、交換できる装備が左に並びます。RGBのソケットを選ぶと、その色に装着できる手持ちジェムが左に並びます。','白いソケットは全色に対応。隣り合うソケットがリンクしていると、サポートジェムが対応するアクティブスキルを強化します。','Bで前のメニューへ戻ります。戻り先がない場合は閉じます。'],gems:['技の設定','スキル枠を選び、装備に装着済みのアクティブジェムを割り当てます。サポートジェムは割り当て不要です。','通常攻撃は各職業固有の1種類です。必殺技は効果の異なる2種類から選びます。どちらもゲージ100を消費し、選択は職業ごとに記憶します。'],skills:['星座とパッシブ','つながったノードを解放して能力を伸ばします。星座を完成すると固有の加護を獲得します。','左スティックで移動、ノードを選んで右側の詳細を確認してください。'],stash:['倉庫','預ける装備と取り出す装備を選び、右側から操作します。'],pause:['メニュー','各画面でBを押すと前のメニューへ戻ります。右上の×は画面を閉じます。']};
function showContextHelp(kind=menuSurface){return menuWrapRoute(function(topic){const data=CONTEXT_MENU_HELP[topic]||['このメニューの使い方','十字キーで項目を選び、Aで決定します。右スティックで詳細をスクロールします。Bで前のメニューへ戻ります。'];worldMenu(data[0],data.slice(1).map(t=>'<p>'+gearEscape(t)+'</p>').join('')+'<button onclick="showGameTips()">すべてのTipsを見る</button>','context-help');},'context-help')(kind);}
function installContextHelp(){if(menuSurface==='gems'){const title=$('card').querySelector('.panel-heading h2');if(title)title.textContent='戦闘スキル';}const heading=$('card').querySelector('.panel-heading');if(!heading||heading.querySelector('.context-help')||!started||dead)return;const close=heading.querySelector('.close');const button=loadoutAction('?',()=>showContextHelp());button.className='context-help';button.setAttribute('aria-label','このメニューのヘルプ');button.title='このメニューのヘルプ';if(close)close.before(button);else heading.prepend(button);}
const contextFrameBase=frameMenu;frameMenu=(...args)=>{const r=contextFrameBase(...args);installContextHelp();return r;};
